import base64
import mimetypes
import os
from dataclasses import dataclass
from typing import Any, BinaryIO, Dict, Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


BytesLike = Union[bytes, bytearray, memoryview]
UploadSource = Union[str, os.PathLike, BytesLike, BinaryIO]


@dataclass
class ManagedObjectUploadResult:
    bucket: str
    key: str
    etag: Optional[str] = None
    version_id: Optional[str] = None
    url: Optional[str] = None
    metadata: Optional[Dict[str, Any]] = None


def _s3_client(region_name: Optional[str] = None):
    return boto3.client("s3", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))


def _read_source(source: UploadSource) -> tuple[bytes, Optional[str]]:
    if isinstance(source, (bytes, bytearray, memoryview)):
        return bytes(source), None
    if isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        with open(path, "rb") as f:
            return f.read(), path
    if hasattr(source, "read"):
        data = source.read()
        if isinstance(data, str):
            data = data.encode("utf-8")
        return bytes(data), getattr(source, "name", None)
    raise TypeError("source must be bytes, path-like, or a binary file object")


def upload_object(
    bucket: str,
    key: str,
    source: UploadSource,
    content_type: Optional[str] = None,
    metadata: Optional[Dict[str, str]] = None,
    region_name: Optional[str] = None,
    extra_args: Optional[Dict[str, Any]] = None,
) -> ManagedObjectUploadResult:
    data, filename = _read_source(source)
    client = _s3_client(region_name)
    resolved_content_type = content_type
    if not resolved_content_type and filename:
        resolved_content_type, _ = mimetypes.guess_type(filename)
    kwargs: Dict[str, Any] = {"Bucket": bucket, "Key": key, "Body": data}
    if resolved_content_type:
        kwargs["ContentType"] = resolved_content_type
    if metadata:
        kwargs["Metadata"] = metadata
    if extra_args:
        kwargs.update(extra_args)
    try:
        response = client.put_object(**kwargs)
    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"failed to upload object to s3://{bucket}/{key}: {exc}") from exc
    etag = response.get("ETag")
    version_id = response.get("VersionId")
    region = client.meta.region_name or region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    url = f"https://{bucket}.s3.{region}.amazonaws.com/{key}" if region else None
    return ManagedObjectUploadResult(bucket=bucket, key=key, etag=etag, version_id=version_id, url=url, metadata=metadata)


def upload_object_from_base64(
    bucket: str,
    key: str,
    data_base64: str,
    content_type: Optional[str] = None,
    metadata: Optional[Dict[str, str]] = None,
    region_name: Optional[str] = None,
) -> ManagedObjectUploadResult:
    return upload_object(bucket, key, base64.b64decode(data_base64), content_type=content_type, metadata=metadata, region_name=region_name)

import os
from dataclasses import dataclass
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class ObjectMetadataResult:
    bucket: str
    key: str
    exists: bool
    content_length: Optional[int] = None
    content_type: Optional[str] = None
    etag: Optional[str] = None
    last_modified: Optional[Any] = None
    storage_class: Optional[str] = None
    version_id: Optional[str] = None
    checksum: Optional[Dict[str, Any]] = None
    metadata: Optional[Dict[str, str]] = None
    raw: Optional[Dict[str, Any]] = None


def _s3_client(region_name: Optional[str] = None):
    return boto3.client("s3", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))


def read_object_metadata(
    bucket: str,
    key: str,
    region_name: Optional[str] = None,
    version_id: Optional[str] = None,
) -> ObjectMetadataResult:
    client = _s3_client(region_name)
    params: Dict[str, Any] = {"Bucket": bucket, "Key": key}
    if version_id:
        params["VersionId"] = version_id
    try:
        response = client.head_object(**params)
    except ClientError as exc:
        error_code = exc.response.get("Error", {}).get("Code")
        if error_code in {"404", "NoSuchKey", "NotFound"}:
            return ObjectMetadataResult(bucket=bucket, key=key, exists=False)
        raise RuntimeError(f"failed to read object metadata for s3://{bucket}/{key}: {exc}") from exc
    except BotoCoreError as exc:
        raise RuntimeError(f"failed to read object metadata for s3://{bucket}/{key}: {exc}") from exc

    return ObjectMetadataResult(
        bucket=bucket,
        key=key,
        exists=True,
        content_length=response.get("ContentLength"),
        content_type=response.get("ContentType"),
        etag=response.get("ETag"),
        last_modified=response.get("LastModified"),
        storage_class=response.get("StorageClass"),
        version_id=response.get("VersionId"),
        checksum={
            k: response.get(k)
            for k in ("ChecksumCRC32", "ChecksumCRC32C", "ChecksumCRC64NVME", "ChecksumSHA1", "ChecksumSHA256")
            if response.get(k) is not None
        }
        or None,
        metadata=response.get("Metadata") or None,
        raw=response,
    )


def object_exists(bucket: str, key: str, region_name: Optional[str] = None, version_id: Optional[str] = None) -> bool:
    return read_object_metadata(bucket=bucket, key=key, region_name=region_name, version_id=version_id).exists

import os
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from typing import Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class PresignedDownloadResult:
    bucket: str
    key: str
    url: str
    expires_in: int
    expires_at: datetime


def _s3_client(region_name: Optional[str] = None):
    return boto3.client("s3", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))


def create_presigned_download_url(
    bucket: str,
    key: str,
    expires_in: int = 3600,
    region_name: Optional[str] = None,
    download_filename: Optional[str] = None,
    response_content_type: Optional[str] = None,
) -> PresignedDownloadResult:
    if expires_in <= 0:
        raise ValueError("expires_in must be greater than 0")
    client = _s3_client(region_name)
    params = {"Bucket": bucket, "Key": key}
    if download_filename:
        params["ResponseContentDisposition"] = f'attachment; filename="{download_filename}"'
    if response_content_type:
        params["ResponseContentType"] = response_content_type
    try:
        url = client.generate_presigned_url(
            ClientMethod="get_object",
            Params=params,
            ExpiresIn=expires_in,
        )
    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"failed to create presigned download url for s3://{bucket}/{key}: {exc}") from exc
    expires_at = datetime.now(timezone.utc) + timedelta(seconds=expires_in)
    return PresignedDownloadResult(bucket=bucket, key=key, url=url, expires_in=expires_in, expires_at=expires_at)

